mapper.select:
/* 수료자 명단 */ SELECT * FROM (SELECT ROW_NUMBER() OVER(PARTITION BY G.TRPR_INFO_NO ORDER BY M.SRTNG_SQNCE DESC) ROW_NO , A.BIZ_YR AS BIZ_YR /*사업년도*/ , D.INST_NO AS INST_NO /*기관번호*/ , D.INST_NM AS INST_NM /*기관명*/ , C.RESRCE_NO AS RESRCE_NO /*자원번호*/ , C.PVSN_RESRCE_NM AS PVSN_RESRCE_NM /*제공자원명*/ , E.CASE_MNG_NO AS CASE_MNG_NO /*사례관리번호*/ , E.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /*사례관리차수*/ , G.TRPR_INFO_NO AS TRPR_INFO_NO /*대상자정보번호*/ , DEC_B64(G.TRPR_NM_ENCPT) AS TRPR_NM /*대상자명암호화*/ , G.TRPR_BRTH_YMD AS TRPR_BRTH_YMD /*대상자출생일자*/ , H.EMPYMN_ERA_SE_CD AS EMPYMN_ERA_SE_CD /*취업시기구분코드(공통)SEA250*/ , H.CO_NM AS CO_NM /*회사명 SEA250*/ , H.SGG_CD AS SGG_CD /*소재지*/ , (SELECT CTPV_NM FROM SAA020 WHERE SGG_CD = H.SGG_CD) AS SGG_CD_NM1 /*시군구코드1*/ , (SELECT SGG_NM FROM SAA020 WHERE SGG_CD = H.SGG_CD) AS SGG_CD_NM2 /*시군구코드2*/ , H.TKCG_TASKWK_CN AS TKCG_TASKWK_CN /*담당업무*/ , H.SALARY_AMT AS SALARY_AMT /*급여금액*/ , H.RM_CN AS RM_CN /*비고내용*/ , CASE -- 1 TRUE WHEN C.PVSN_BGNG_YMD < J.ACQS_YMD THEN 1 ELSE 0 END AS QLFC , CASE -- 1 TRUE WHEN C.PVSN_BGNG_YMD < I.MTCLTN_YMD THEN 1 ELSE 0 END AS DGRICD , I.MNG_SN /*진학여부 SEA230 학력상태*/ , K.CMMNS_CD_VALUE /*종결구분코드(공통) => 00 종결로 변경 TRMN_SE_CD*/ , K.CMMNS_CD_VALUE_NM AS CMMNS_CD_VALUE_NM , M.CMMNS_CD_VALUE_NM AS ACBG , M.SRTNG_SQNCE FROM SDA400 A /*서비스사업*/ JOIN SDA420 B /*서비스실행사업*/ ON A.SRVC_BIZ_NO = B.SRVC_BIZ_NO JOIN SDA100 C /*자원기본*/ ON B.SRVC_EXCN_BIZ_NO = C.SRVC_EXCN_BIZ_NO JOIN SAA000 D /*통합기관*/ ON C.RSFR_INST_NO = D.INST_NO JOIN SEB510 E /*서비스제공대상자*/ ON C.RESRCE_NO = E.RESRCE_NO LEFT JOIN SEB100 L ON E.CASE_MNG_NO = L.CASE_MNG_NO AND E.CASE_MNG_ODRNO = L.CASE_MNG_ODRNO LEFT JOIN (SELECT BB.CASE_MNG_NO, BB.CASE_MNG_ODRNO, BB.TRMN_CS_SE_CD, AA.CASE_TRMN_YMD, BB.TRMN_SE_CD, BB.YNGBGS_CHNG_LAST_RESULT_CN, AA.PIC_OPNN_CN ,ROW_NUMBER() OVER(PARTITION BY BB.CASE_MNG_NO, BB.CASE_MNG_ODRNO ORDER BY BB.CASE_TRMN_NO DESC) AS RN FROM SEC100 AA /*사례종결 테이블*/ LEFT JOIN SEC100 BB ON BB.CASE_MNG_NO = AA.CASE_MNG_NO AND BB.CASE_MNG_NO = AA.CASE_MNG_NO AND BB.TRMN_SRNG_RESULT_SE_CD = '01' /*종결심사결과구분코드(신청)*/ WHERE AA.TRMN_SRNG_RESULT_SE_CD = '02' /*종결심사결과구분코드(심사(승인))*/ )F ON F.CASE_MNG_NO = E.CASE_MNG_NO AND F.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO AND F.RN=1 JOIN SEA200 G /*대상자정보*/ ON G.TRPR_INFO_NO = L.TRPR_INFO_NO LEFT JOIN SEA250 H /*취업정보*/ ON G.TRPR_INFO_NO = H.TRPR_INFO_NO LEFT JOIN SEA230 I /*학력상태*/ ON G.TRPR_INFO_NO = I.TRPR_INFO_NO LEFT JOIN SEA260 J /*자격증취득여부*/ ON G.TRPR_INFO_NO = J.TRPR_INFO_NO LEFT JOIN SAC100 K /*종결사유구분코드*/ ON K.CMMNS_CD_ID = 'TRMN_CS_SE_CD' AND K.CMMNS_CD_VALUE = F.TRMN_CS_SE_CD LEFT JOIN SAC100 M ON M.CMMNS_CD_ID = 'ACBG_SE_CD' /* 최종학력구분코드 */ AND M.CMMNS_CD_VALUE = I.ACBG_SE_CD WHERE D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND F.TRMN_CS_SE_CD IN ('042', '043', '044' ,'045', '046', '047') AND A.BIZ_YR LIKE #{BIZ_YR} || '%' AND D.INST_NO LIKE #{INST_NO} || '%' AND C.RESRCE_NO LIKE #{RESRCE_NO} || '%'
AND G.TRPR_NM_ENCPT = ENC_B64(#{TRPR_NM})
AND C.SRVC_RESRCE_LCLAS_SE_CD <> '01' AND C.APRV_STTS_SE_CD = '2' ) A WHERE ROW_NO = 1

/* 기타자 명단 */ SELECT * FROM (SELECT ROW_NUMBER() OVER(PARTITION BY G.TRPR_INFO_NO ORDER BY M.SRTNG_SQNCE DESC) ROW_NO , A.BIZ_YR AS BIZ_YR /*사업년도*/ , D.INST_NO AS INST_NO /*기관번호*/ , D.INST_NM AS INST_NM /*기관명*/ , C.RESRCE_NO AS RESRCE_NO /*자원번호*/ , C.PVSN_RESRCE_NM AS PVSN_RESRCE_NM /*제공자원명*/ , E.CASE_MNG_NO AS CASE_MNG_NO /*사례관리번호*/ , E.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /*사례관리차수*/ , G.TRPR_INFO_NO AS TRPR_INFO_NO /*대상자정보번호*/ , DEC_B64(G.TRPR_NM_ENCPT) AS TRPR_NM /*대상자명암호화*/ , G.TRPR_BRTH_YMD AS TRPR_BRTH_YMD /*대상자출생일자*/ , H.EMPYMN_ERA_SE_CD AS EMPYMN_ERA_SE_CD /*취업시기구분코드*/ , H.CO_NM AS CO_NM /*회사명*/ , H.SGG_CD AS SGG_CD /*소재지*/ , H.TKCG_TASKWK_CN AS TKCG_TASKWK_CN /*담당업무*/ , H.SALARY_AMT AS SALARY_AMT /*급여금액*/ , H.RM_CN AS RM_CN /*비고내용*/ , CASE -- 1 TRUE WHEN C.PVSN_BGNG_YMD < J.ACQS_YMD THEN 1 ELSE 0 END AS QLFC , J.QLFC_INFO_MNG_NO AS QLFC_INFO_MNG_NO /*자격증취득여부*/ , I.MNG_SN AS MNG_SN /*진학여부*/ , K.CMMNS_CD_VALUE , K.CMMNS_CD_VALUE_NM , M.CMMNS_CD_VALUE_NM AS ACBG , M.SRTNG_SQNCE FROM SDA400 A /*서비스사업*/ JOIN SDA420 B /*서비스실행사업*/ ON A.SRVC_BIZ_NO = B.SRVC_BIZ_NO JOIN SDA100 C /*자원기본*/ ON B.SRVC_EXCN_BIZ_NO = C.SRVC_EXCN_BIZ_NO JOIN SAA000 D /*통합기관*/ ON C.RSFR_INST_NO = D.INST_NO LEFT JOIN SEB510 E /*서비스제공대상자*/ ON C.RESRCE_NO = E.RESRCE_NO LEFT JOIN SEB100 L /*사례기본*/ ON E.CASE_MNG_NO = L.CASE_MNG_NO AND E.CASE_MNG_ODRNO = L.CASE_MNG_ODRNO LEFT JOIN (SELECT BB.CASE_MNG_NO, BB.CASE_MNG_ODRNO, BB.TRMN_CS_SE_CD, AA.CASE_TRMN_YMD, BB.TRMN_SE_CD, BB.YNGBGS_CHNG_LAST_RESULT_CN, AA.PIC_OPNN_CN ,ROW_NUMBER() OVER(PARTITION BY BB.CASE_MNG_NO, BB.CASE_MNG_ODRNO ORDER BY BB.CASE_TRMN_NO DESC) AS RN FROM SEC100 AA /*사례종결 테이블*/ LEFT JOIN SEC100 BB ON BB.CASE_MNG_NO = AA.CASE_MNG_NO AND BB.CASE_MNG_NO = AA.CASE_MNG_NO AND BB.TRMN_SRNG_RESULT_SE_CD = '01' /*종결심사결과구분코드(신청)*/ WHERE AA.TRMN_SRNG_RESULT_SE_CD = '02' /*종결심사결과구분코드(심사(승인))*/ )F ON F.CASE_MNG_NO = E.CASE_MNG_NO AND F.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO AND F.RN=1 LEFT JOIN SEA200 G /*대상자정보*/ ON G.TRPR_INFO_NO = L.TRPR_INFO_NO LEFT JOIN SEA250 H /*취업정보*/ ON G.TRPR_INFO_NO = H.TRPR_INFO_NO LEFT JOIN SEA230 I /*학력상태*/ ON G.TRPR_INFO_NO = I.TRPR_INFO_NO LEFT JOIN SCA111 J /*자격증취득여부*/ ON G.QLFC_INFO_MNG_NO = J.QLFC_INFO_MNG_NO LEFT JOIN SAC100 K /*종결구분*/ ON K.CMMNS_CD_ID = 'TRMN_SE_CD' AND K.CMMNS_CD_VALUE = F.TRMN_SE_CD LEFT JOIN SAC100 N /*종결사유구분코드*/ ON N.CMMNS_CD_ID = 'TRMN_CS_SE_CD' AND N.CMMNS_CD_VALUE = F.TRMN_CS_SE_CD LEFT JOIN SAC100 M ON M.CMMNS_CD_ID = 'ACBG_SE_CD' /* 최종학력구분코드 */ AND M.CMMNS_CD_VALUE = I.ACBG_SE_CD WHERE D.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND F.TRMN_CS_SE_CD IN ('048') AND A.BIZ_YR LIKE #{BIZ_YR} || '%' AND D.INST_NO LIKE #{INST_NO} || '%' AND C.RESRCE_NO LIKE #{RESRCE_NO} || '%'
AND G.TRPR_NM_ENCPT = ENC_B64(#{TRPR_NM})
AND C.SRVC_RESRCE_LCLAS_SE_CD <> '01' AND C.APRV_STTS_SE_CD = '2' ) A WHERE ROW_NO = 1

/* 학력취득자 명단 */ SELECT MNG_SN, BIZ_YR, INST_NM, INST_NO, RESRCE_NO, PVSN_RESRCE_NM, CASE_MNG_NO, CASE_MNG_ODRNO, TRPR_INFO_NO, TRPR_NM, TRPR_BRTH_YMD, ACQRE_ACDM, DGRI, GRDTN, ACBG FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY F.TRPR_INFO_NO ORDER BY J.SRTNG_SQNCE DESC, H.SRTNG_SQNCE DESC) ROW_NO , A.BIZ_YR AS BIZ_YR /*사업년도*/ , I.INST_NM AS INST_NM /*기관명*/ , I.INST_NO AS INST_NO /*기관번호*/ , C.RESRCE_NO AS RESRCE_NO /*자원번호*/ , C.PVSN_RESRCE_NM AS PVSN_RESRCE_NM /*제공자원명*/ , D.CASE_MNG_NO AS CASE_MNG_NO /*사례관리번호*/ , D.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /*사례관리차수*/ , F.TRPR_INFO_NO AS TRPR_INFO_NO /*대상자정보번호*/ , DEC_B64(F.TRPR_NM_ENCPT) AS TRPR_NM /*대상자명암호화*/ , F.TRPR_BRTH_YMD AS TRPR_BRTH_YMD /*대상자출생일자*/ , G.DGRI_ACQS_ERA_YM AS ACQRE_ACDM /*학위취득시기연월*/ , G.DGRI_ACQS_MTHD_SE_CD AS DGRI /*학위취득방법구분코드*/ , H.CMMNS_CD_VALUE_NM AS GRDTN /* 공통 */ , J.CMMNS_CD_VALUE_NM AS ACBG , J.SRTNG_SQNCE , H.SRTNG_SQNCE , M.CMMNS_CD_VALUE , M.CMMNS_CD_VALUE_NM , N.CMMNS_CD_VALUE , N.CMMNS_CD_VALUE_NM , K.MNG_SN , L.TRMN_SE_CD FROM SDA400 A /*서비스 사업*/ JOIN SDA420 B /*서비스 실행사업*/ ON A.SRVC_BIZ_NO = B.SRVC_BIZ_NO JOIN SDA100 C /*자원기본*/ ON B.SRVC_EXCN_BIZ_NO = C.SRVC_EXCN_BIZ_NO JOIN SAA000 I ON C.RSFR_INST_NO = I.INST_NO LEFT JOIN SEB510 D /*서비스제공대상자*/ ON C.RESRCE_NO = D.RESRCE_NO LEFT JOIN SEB100 E /*사례기본*/ ON E.CASE_MNG_NO = D.CASE_MNG_NO AND E.CASE_MNG_ODRNO = D.CASE_MNG_ODRNO LEFT JOIN (SELECT BB.CASE_MNG_NO, BB.CASE_MNG_ODRNO, BB.TRMN_CS_SE_CD, AA.CASE_TRMN_YMD, BB.TRMN_SE_CD, BB.YNGBGS_CHNG_LAST_RESULT_CN, AA.PIC_OPNN_CN ,ROW_NUMBER() OVER(PARTITION BY BB.CASE_MNG_NO, BB.CASE_MNG_ODRNO ORDER BY BB.CASE_TRMN_NO DESC) AS RN FROM SEC100 AA /*사례종결 테이블*/ LEFT JOIN SEC100 BB ON BB.CASE_MNG_NO = AA.CASE_MNG_NO AND BB.CASE_MNG_ODRNO = AA.CASE_MNG_ODRNO AND BB.TRMN_SRNG_RESULT_SE_CD = '01' /*종결심사결과구분코드(신청)*/ WHERE AA.TRMN_SRNG_RESULT_SE_CD = '02' /*종결심사결과구분코드(심사(승인))*/ )L ON L.CASE_MNG_NO = E.CASE_MNG_NO AND L.CASE_MNG_ODRNO = E.CASE_MNG_ODRNO AND L.RN=1 LEFT JOIN SEA200 F /*대상자정보*/ ON F.TRPR_INFO_NO = E.TRPR_INFO_NO LEFT JOIN SEA250 K ON F.TRPR_INFO_NO = K.TRPR_INFO_NO LEFT JOIN SEA230 G /*학력상태*/ ON F.TRPR_INFO_NO = G.TRPR_INFO_NO LEFT JOIN SAC100 H ON H.CMMNS_CD_ID = 'GRDTN_STTS_SE_CD' /* 졸업상태구분코드 */ AND H.CMMNS_CD_VALUE = G.GRDTN_STTS_SE_CD LEFT JOIN SAC100 J ON J.CMMNS_CD_ID = 'ACBG_SE_CD' /* 최종학력구분코드 */ AND J.CMMNS_CD_VALUE = G.ACBG_SE_CD LEFT JOIN SAC100 M /*종결구분코드*/ ON M.CMMNS_CD_ID = 'TRMN_SE_CD' AND M.CMMNS_CD_VALUE = L.TRMN_SE_CD LEFT JOIN SAC100 N /*종결사유구분코드*/ ON N.CMMNS_CD_ID = 'TRMN_CS_SE_CD' AND N.CMMNS_CD_VALUE = L.TRMN_CS_SE_CD WHERE I.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} /* 20230807 종결여부와 상관없이 학력 성과가 등록된 대상자 조회 */ AND (G.OUTC_SE_CD = '2' OR L.TRMN_CS_SE_CD IN ('043', '045', '046', '055')) AND A.BIZ_YR LIKE #{BIZ_YR} || '%' AND I.INST_NO LIKE #{INST_NO} || '%' AND C.RESRCE_NO LIKE #{RESRCE_NO} || '%'
AND F.TRPR_NM_ENCPT = ENC_B64(#{TRPR_NM})
AND C.SRVC_RESRCE_LCLAS_SE_CD <> '01' AND C.APRV_STTS_SE_CD = '2' ) A WHERE ROW_NO = 1 AND ACBG IS NOT NULL AND GRDTN IS NOT NULL

/* 상세 - 기본정보*/ SELECT A.CASE_MNG_NO AS CASE_MNG_NO /* 사례관리번호 */ , A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ , A.TRPR_INFO_NO AS TRPR_INFO_NO /* 대상자정보번호 */ , A.CASE_BGNG_YMD AS CASE_BGNG_YMD /* 사례시작일자 */ , A.CASE_TRMN_YMD AS CASE_TRMN_YMD /* 사례종결일자 */ , A.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , A.YNGBGS_STTS_LCLAS_SE_CD AS YNGBGS_STTS_LCLAS_SE_CD /* 청소년상태대분류구분코드 */ , A.YNGBGS_STTS_SCLAS_SE_CD AS YNGBGS_STTS_SCLAS_SE_CD /* 청소년상태소분류구분코드 */ , A.RESDN_SHAPE_SE_CD AS RESDN_SHAPE_SE_CD /* 거주형태구분코드 */ , A.FAM_CHAR_SE_CD AS FAM_CHAR_SE_CD /* 가족특성구분코드 */ , A.RESIDE_SHAPE_SE_CD AS RESIDE_SHAPE_SE_CD /* 주거형태구분코드 */ , A.RESIDE_SHAPE_ETC_CN AS RESIDE_SHAPE_ETC_CN /* 주거형태기타내용 */ , A.HEALTH_PROBM_CN AS HEALTH_PROBM_CN /* 건강문제내용 */ , A.TAKNG_DRFSTF_CN AS TAKNG_DRFSTF_CN /* 복용약물내용 */ , A.CASE_PRGRS_STTS_SE_CD AS CASE_PRGRS_STTS_SE_CD /* 사례진행상태구분코드 */ , A.TAG_NM AS TAG_NM /* 태그명 */ , A.TAG_NO AS TAG_NO /* 태그번호 */ , B.INDV_IDNTFC_NO AS INDV_IDNTFC_NO /* 개인식별번호 */ , DEC_B64(B.TRPR_NM_ENCPT) AS TRPR_NM_ENCPT /* 대상자명 */ , TO_CHAR(TO_DATE(B.TRPR_BRTH_YMD), 'YYYY-MM-DD') AS TRPR_BRTH_YMD /* 대상자출생일자 */ , B.SXDC_SE_CD AS SXDC_SE_CD /* 대상자성별구분코드 */ , B.MRG_YN AS MRG_YN /* 결혼여부 */ , B.TRPR_TELNO AS TRPR_TELNO_ENCPT /* 대상자전화번호 */ , DEC_B64(B.MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT /* 휴대전화번호 */ , DEC_B64(B.EML_ADDR_ENCPT) AS EML_ADDR_ENCPT /* 이메일주소 */ , B.SNS_SE_CD AS SNS_SE_CD /* SNS구분코드 */ , B.MSNGR_ID_ENCPT AS MSNGR_ID_ENCPT /* 메신저아이디 */ , B.ZIP AS ZIP /* 우편번호 */ , B.PST_ADDR AS PST_ADDR /* 우편주소 */ , B.DADDR AS DADDR /* 상세주소 */ , B.ACBG_SE_CD AS ACBG_SE_CD /* 학력구분코드 */ , B.GRDTN_STTS_SE_CD AS GRDTN_STTS_SE_CD /* 졸업상태구분코드 */ , B.GRADE_SE_CD AS GRADE_SE_CD /* 학년구분코드 */ , B.PSPT_ENG_FLNM_ENCPT AS PSPT_ENG_FLNM_ENCPT /* 여권영문성명 */ , B.TRPR_BCRN_TYPE_SE_CD AS TRPR_BCRN_TYPE_SE_CD /* 대상자배경유형구분코드 */ , B.TRPR_BCRN_TYPE_RM_NM AS TRPR_BCRN_TYPE_RM_NM /* 대상자배경유형비고명 */ , B.NLTY_NTN_SE_CD AS NLTY_NTN_SE_CD /* 국적국가구분코드 */ , B.ENTCNY_YMD AS ENTCNY_YMD /* 입국일자 */ , B.BRTH_NTN_SE_CD AS BRTH_NTN_SE_CD /* 출생국가구분코드 */ , B.GROWTH_NTN_SE_CD AS GROWTH_NTN_SE_CD /* 성장국가구분코드 */ , B.VISA_TYPE_SE_CD AS VISA_TYPE_SE_CD /* 비자유형구분코드 */ , B.HANAWO_PENU_NO AS HANAWO_PENU_NO /* 하나원기수번호 */ , B.RELGN_SE_CD AS RELGN_SE_CD /* 종교구분코드 */ , B.UNT_TASKWK_SE_CD AS UNT_TASKWK_SE_CD /* 단위업무구분코드 */ , B.RCPT_PIC_NO AS RCPT_PIC_NO /* 접수담당자번호 */ , B.RCPT_INST_NO AS RCPT_INST_NO /* 접수기관번호 */ , B.CASE_TRPR_TYPE_SE_CD AS CASE_TRPR_TYPE_SE_CD /* 사례대상자유형구분코드 */ , B.CASE_TRPR_SLCTN_YMD AS CASE_TRPR_SLCTN_YMD /* 사례대상자선정일자 */ , B.CASE_TRPR_UNSL_CS_CN AS CASE_TRPR_UNSL_CS_CN /* 사례대상자미선정사유내용 */ , B.PRTCR_NM_ENCPT AS PRTCR_NM_ENCPT /* 보호자명 */ , B.TRPR_REL_SE_CD AS TRPR_REL_SE_CD /* 대상자관계구분코드 */ , B.LIVTGT_YN AS LIVTGT_YN /* 동거여부 */ , B.PRTCR_AGRE_YN AS PRTCR_AGRE_YN /* 보호자동의여부 */ , B.PRVC_PVSN_AGRE_YN AS PRVC_PVSN_AGRE_YN /* 개인정보제공동의여부 */ , B.SRVC_CTRT_AGRE_YN AS SRVC_CTRT_AGRE_YN /* 서비스계약동의여부 */ , B.QLFC_INFO_MNG_NO AS QLFC_INFO_MNG_NO /* 자격정보관리번호 */ FROM SEB100 A JOIN SEA200 B ON B.TRPR_INFO_NO = A.TRPR_INFO_NO WHERE 1 = 1
AND A.CASE_MNG_NO = #{CASE_MNG_NO} AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
AND B.TRPR_INFO_NO = #{TRPR_INFO_NO}
